from math_utils import normalize_whitespace


def test_collapses_spaces_and_trims_edges():
    assert normalize_whitespace("  hello   world  ") == "hello world"


def test_collapses_tabs_and_newlines():
    assert normalize_whitespace("hello\tworld\nagain") == "hello world again"


def test_empty_and_whitespace_only_input():
    assert normalize_whitespace("") == ""
    assert normalize_whitespace(" \t\n ") == ""

