import pytest
from csv_utils import parse_csv_row


def test_parses_quoted_commas():
    assert parse_csv_row('Ada,42,"Seattle, WA"') == ["Ada", "42", "Seattle, WA"]


def test_parses_escaped_quotes():
    assert parse_csv_row('"She said ""hello"""') == ['She said "hello"']


def test_parses_empty_fields():
    assert parse_csv_row("a,,c") == ["a", "", "c"]
